function ys(bi: string, ma : string, ta : string) : string {
    let s : string = ""
    for (let i : number = 0; i < 4; i++) {
        if (i == 3) {
            s = ma + s
        } else if (i == 0) {
            s = s + bi
        } else {
            s = ta + s
        }
    }
    return s
}

function fatorial(n : number) : number {
    let resultado : number = 0

    for (let i : integer = 0; i < n; i++) {
        resultado = resultado + i
    }

    return resultado
}

function li(l : number, c : number, m : number) : string {
    if (c == m + 1) return "\n"

    return ((l == c) ? "\\" : ((l + c == m) ? "/" : ".")) + (li(l, c+1, m))    
}

function co(l : number, c : number, m : number) : string {
    if (l == m + 1) return ""

   return li(l, c, m) + co(l +1, c, m)
}
